import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.lkcCxhZm.js";const p=JSON.parse('{"title":"Class: CST","description":"","frontmatter":{},"headers":[],"relativePath":"api/reference/cst/xml-cst/classes/CST.md","filePath":"api/reference/cst/xml-cst/classes/CST.md"}'),n={name:"api/reference/cst/xml-cst/classes/CST.md"};function s(d,e,i,c,h,l){return a(),r("div",null,[...e[0]||(e[0]=[o('<p><a href="./../../../README.html"><strong>@miy2/xml-api</strong></a></p><hr><h1 id="class-cst" tabindex="-1">Class: CST <a class="header-anchor" href="#class-cst" aria-label="Permalink to &quot;Class: CST&quot;">​</a></h1><p>Represents a node in the Concrete Syntax Tree (Parse Tree). Each node corresponds to a match of a grammatical structure or rule.</p><h2 id="constructors" tabindex="-1">Constructors <a class="header-anchor" href="#constructors" aria-label="Permalink to &quot;Constructors&quot;">​</a></h2><h3 id="constructor" tabindex="-1">Constructor <a class="header-anchor" href="#constructor" aria-label="Permalink to &quot;Constructor&quot;">​</a></h3><blockquote><p><strong>new CST</strong>(<code>type</code>, <code>name</code>, <code>start</code>, <code>end</code>, <code>children</code>, <code>wellFormed</code>): <code>CST</code></p></blockquote><h4 id="parameters" tabindex="-1">Parameters <a class="header-anchor" href="#parameters" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="type" tabindex="-1">type <a class="header-anchor" href="#type" aria-label="Permalink to &quot;type&quot;">​</a></h5><p><code>string</code></p><p>The type of the grammatical structure matched. Common values include &quot;literal&quot;, &quot;regex&quot;, &quot;sequence&quot;, &quot;repeat&quot;. This describes the structural nature of the match, not the grammar rule name.</p><h5 id="name" tabindex="-1">name <a class="header-anchor" href="#name" aria-label="Permalink to &quot;name&quot;">​</a></h5><p>The name of the grammar rule corresponding to this node (e.g., &quot;element&quot;, &quot;attribute&quot;). Defined only if this node represents a named rule reference; otherwise undefined.</p><p><code>string</code> | <code>undefined</code></p><h5 id="start" tabindex="-1">start <a class="header-anchor" href="#start" aria-label="Permalink to &quot;start&quot;">​</a></h5><p><code>number</code></p><p>The 0-based starting index of this node in the entire input string (inclusive).</p><h5 id="end" tabindex="-1">end <a class="header-anchor" href="#end" aria-label="Permalink to &quot;end&quot;">​</a></h5><p><code>number</code></p><p>The 0-based ending index of this node in the entire input string (exclusive). The length of the match is (end - start).</p><h5 id="children" tabindex="-1">children <a class="header-anchor" href="#children" aria-label="Permalink to &quot;children&quot;">​</a></h5><p><code>CST</code>[] = <code>[]</code></p><p>Child nodes contained within this structure. Empty for leaf nodes like literals or regex matches.</p><h5 id="wellformed" tabindex="-1">wellFormed <a class="header-anchor" href="#wellformed" aria-label="Permalink to &quot;wellFormed&quot;">​</a></h5><p><code>boolean</code> = <code>true</code></p><p>Indicates whether the node satisfies additional validation logic beyond basic parsing. If false, the node was parsed successfully according to the grammar structure but failed a semantic or contextual validation check.</p><h4 id="returns" tabindex="-1">Returns <a class="header-anchor" href="#returns" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>CST</code></p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="children-1" tabindex="-1">children <a class="header-anchor" href="#children-1" aria-label="Permalink to &quot;children&quot;">​</a></h3><blockquote><p><strong>children</strong>: <code>CST</code>[] = <code>[]</code></p></blockquote><p>Child nodes contained within this structure. Empty for leaf nodes like literals or regex matches.</p><hr><h3 id="end-1" tabindex="-1">end <a class="header-anchor" href="#end-1" aria-label="Permalink to &quot;end&quot;">​</a></h3><blockquote><p><strong>end</strong>: <code>number</code></p></blockquote><p>The 0-based ending index of this node in the entire input string (exclusive). The length of the match is (end - start).</p><hr><h3 id="name-1" tabindex="-1">name <a class="header-anchor" href="#name-1" aria-label="Permalink to &quot;name&quot;">​</a></h3><blockquote><p><strong>name</strong>: <code>string</code> | <code>undefined</code></p></blockquote><p>The name of the grammar rule corresponding to this node (e.g., &quot;element&quot;, &quot;attribute&quot;). Defined only if this node represents a named rule reference; otherwise undefined.</p><hr><h3 id="parent" tabindex="-1">parent <a class="header-anchor" href="#parent" aria-label="Permalink to &quot;parent&quot;">​</a></h3><blockquote><p><strong>parent</strong>: <code>CST</code> | <code>null</code> = <code>null</code></p></blockquote><p>Reference to the parent node in the syntax tree. Null if this is the root node.</p><hr><h3 id="start-1" tabindex="-1">start <a class="header-anchor" href="#start-1" aria-label="Permalink to &quot;start&quot;">​</a></h3><blockquote><p><strong>start</strong>: <code>number</code></p></blockquote><p>The 0-based starting index of this node in the entire input string (inclusive).</p><hr><h3 id="type-1" tabindex="-1">type <a class="header-anchor" href="#type-1" aria-label="Permalink to &quot;type&quot;">​</a></h3><blockquote><p><strong>type</strong>: <code>string</code></p></blockquote><p>The type of the grammatical structure matched. Common values include &quot;literal&quot;, &quot;regex&quot;, &quot;sequence&quot;, &quot;repeat&quot;. This describes the structural nature of the match, not the grammar rule name.</p><hr><h3 id="wellformed-1" tabindex="-1">wellFormed <a class="header-anchor" href="#wellformed-1" aria-label="Permalink to &quot;wellFormed&quot;">​</a></h3><blockquote><p><strong>wellFormed</strong>: <code>boolean</code> = <code>true</code></p></blockquote><p>Indicates whether the node satisfies additional validation logic beyond basic parsing. If false, the node was parsed successfully according to the grammar structure but failed a semantic or contextual validation check.</p><h2 id="methods" tabindex="-1">Methods <a class="header-anchor" href="#methods" aria-label="Permalink to &quot;Methods&quot;">​</a></h2><h3 id="gettext" tabindex="-1">getText() <a class="header-anchor" href="#gettext" aria-label="Permalink to &quot;getText()&quot;">​</a></h3><blockquote><p><strong>getText</strong>(<code>input</code>): <code>string</code></p></blockquote><p>Retrieves the substring matching this node from the entire original input string.</p><h4 id="parameters-1" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-1" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="input" tabindex="-1">input <a class="header-anchor" href="#input" aria-label="Permalink to &quot;input&quot;">​</a></h5><p><code>string</code></p><h4 id="returns-1" tabindex="-1">Returns <a class="header-anchor" href="#returns-1" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>string</code></p><hr><h3 id="shift" tabindex="-1">shift() <a class="header-anchor" href="#shift" aria-label="Permalink to &quot;shift()&quot;">​</a></h3><blockquote><p><strong>shift</strong>(<code>pos</code>, <code>delta</code>): <code>void</code></p></blockquote><p>Shifts the start and end positions of this node and its children.</p><h4 id="parameters-2" tabindex="-1">Parameters <a class="header-anchor" href="#parameters-2" aria-label="Permalink to &quot;Parameters&quot;">​</a></h4><h5 id="pos" tabindex="-1">pos <a class="header-anchor" href="#pos" aria-label="Permalink to &quot;pos&quot;">​</a></h5><p><code>number</code></p><p>The position where the change occurred.</p><h5 id="delta" tabindex="-1">delta <a class="header-anchor" href="#delta" aria-label="Permalink to &quot;delta&quot;">​</a></h5><p><code>number</code></p><p>The change in length.</p><h4 id="returns-2" tabindex="-1">Returns <a class="header-anchor" href="#returns-2" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>void</code></p><hr><h3 id="unwrap" tabindex="-1">unwrap() <a class="header-anchor" href="#unwrap" aria-label="Permalink to &quot;unwrap()&quot;">​</a></h3><blockquote><p><strong>unwrap</strong>(): <code>CST</code></p></blockquote><p>Unwraps single-child Reference nodes to find the underlying structural node.</p><h4 id="returns-3" tabindex="-1">Returns <a class="header-anchor" href="#returns-3" aria-label="Permalink to &quot;Returns&quot;">​</a></h4><p><code>CST</code></p>',84)])])}const m=t(n,[["render",s]]);export{p as __pageData,m as default};
